  <style>
    @font-face { font-family:"Alibaba Sans Price"; src:url("{{ asset('fonts/AlibabaSans102-Md.ttf') }}") format("truetype"); font-style:normal; font-weight:500; font-display:swap; }
    :root { --orange:#ff5b00; --green:#28ac70; --ink:#333; --muted:#999; --line:#f1f1f1; --page:#f3f4f6; }
    * { box-sizing:border-box; }
    html { background:var(--page); }
    body { position:relative; display:grid; grid-template-columns:200px minmax(0,1fr); margin:0; min-width:1680px; color:var(--ink); font:14px/1.5 Arial,"PingFang SC","Microsoft YaHei",sans-serif; }
    button,input,select { font:inherit; color:inherit; }
    button { cursor:pointer; }
    button:disabled { cursor:default; }
    a { color:inherit; text-decoration:none; }
    button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible { outline:2px solid var(--orange); outline-offset:2px; }
    button { background:none; border:0; }
    .sprite { flex-shrink:0; display:block; background-image:url('data:image/png;base64,'); background-repeat:no-repeat; background-size:3440px 3377px; }
    .icon { width:20px; height:20px; fill:none; stroke:currentColor; stroke-width:1.35; stroke-linecap:round; stroke-linejoin:round; vertical-align:middle; flex-shrink:0; }
    .chevron { display:inline-block; width:7px; height:7px; border-right:1px solid currentColor; border-bottom:1px solid currentColor; transform:rotate(45deg); margin:-4px 2px 0 7px; vertical-align:middle; opacity:.65; }
    .chevron.up { transform:rotate(225deg); margin-top:3px; }
    .copy { display:inline-block; width:10px; height:10px; position:relative; margin-left:5px; color:#d5d6e2; }
    .copy::before,.copy::after { content:""; position:absolute; width:6px; height:6px; border:1px solid currentColor; border-radius:1px; }
    .copy::before { top:0; left:3px; } .copy::after { top:3px; left:0; background:#fbfbfd; }
    .site-header { grid-column:1 / -1; height:64px; background:#fff; position:relative; display:flex; align-items:center; justify-content:space-between; padding:0 80px; }
    .brand { width:88px; height:36px; display:block; flex-shrink:0; }
