    .top-link .icon { height:22px; margin-bottom:1px; }
    .message-count { position:absolute; top:7px; right:13px; display:flex; align-items:center; justify-content:center; padding:0; text-align:center; font:10px/1 Arial,sans-serif; width:14px; height:14px; border-radius:50%; color:#fff; background:var(--orange); }
    .avatar { display:block; flex-shrink:0; width:40px; height:44px; margin:9px 0 0 52px; overflow:hidden; }
    .sidebar { grid-column:1; grid-row:2; width:210px; padding:10px 0 24px; background:#fff; border-right:8px solid #f5f5f6; }
    .sidebar-groups,.sidebar-links { list-style:none; margin:0; padding:0; }
    .sidebar-group + .sidebar-group { margin-top:10px; }
    .sidebar-heading { display:flex; align-items:center; justify-content:space-between; height:24px; padding:0 37px 0 29px; line-height:24px; color:#999; font-size:14px; list-style:none; cursor:pointer; }
    .sidebar-heading::-webkit-details-marker { display:none; }
    .sidebar-heading .chevron { width:7px; height:7px; margin:0; color:#8b8b8b; flex-shrink:0; }
    .sidebar-group details[open] > .sidebar-heading .chevron { transform:rotate(225deg); }
    .sidebar-links { margin-top:8px; }
    .sidebar-item { display:block; width:194px; height:32px; padding-left:44px; line-height:32px; white-space:nowrap; }
    .sidebar-item.active { background:var(--orange); color:#fff; font-weight:600; }
    .workspace { grid-column:2; grid-row:2; min-height:calc(100vh - 64px); padding:16px 0 30px; }
    .content { width:1440px; margin:0 auto; }
