    .notice .close { position:absolute; right:12px; top:0; font-size:24px; font-weight:300; color:#999; }
    .work-tabs { height:54px; padding-top:12px; display:flex; align-items:stretch; color:#9195af; gap:0; }
    .work-tab { height:42px; padding:0 20px; display:flex; align-items:center; gap:6px; font-size:16px; position:relative; }
    .work-tab.active { color:#333; background:white; border-radius:12px 12px 0 0; font-weight:600; }
    .work-tab.active::before { content:""; position:absolute; right:-16px; bottom:0; width:16px; height:16px; background:radial-gradient(circle at 100% 0px, transparent 16px, rgb(255, 255, 255) 16px); pointer-events:none; }
    .work-tab:not(:first-child)::after { content:""; width:1px; height:10px; background:#e3e4ec; position:absolute; top:16px; right:0; }
    .work-tab .icon { width:19px; height:19px; }
