    .field input,.field select,.control { border:1px solid #ddd; height:32px; border-radius:4px; background:#fff; width:100%; min-width:0; padding:0 8px; font-size:12px; outline-offset:0; }
    input::placeholder { color:#c8c8c8; opacity:1; }
