    .price-input { position:relative; min-width:0; }
    .price-input span { position:absolute; left:8px; top:5px; color:#c3c3c3; }
    .price-input input { padding-left:25px; }
    .filter-actions { grid-column:span 2; display:flex; justify-content:flex-end; align-items:center; gap:8px; height:32px; }
    .ai-filter { display:flex; align-items:center; gap:10px; font-size:12px; margin-right:8px; }
    .switch { width:40px; height:24px; background:#d3d3d3; border-radius:16px; padding:3px; }
    .switch::after { content:""; display:block; width:18px; height:18px; background:white; border-radius:50%; }
    .switch[aria-checked="true"] { background:var(--orange); }
    .switch[aria-checked="true"]::after { margin-left:16px; }
    .collapse-filter { color:#aaa; font-size:12px; border-left:1px solid #eee; padding:0 4px 0 10px; margin-right:6px; }
    .btn { display:inline-flex; align-items:center; justify-content:center; gap:4px; height:32px; border:1px solid #d5d5d5; background:#fff; border-radius:4px; padding:0 16px; white-space:nowrap; }
    .btn.primary { color:#fff; background:var(--orange); border-color:var(--orange); font-weight:600; }
    .btn.default { color:#000; background:#f5f5f5; border-color:#f5f5f5; font-weight:600; }
    .btn:disabled { color:#bbb; border-color:#eee; }
    .btn.w100 {width:100px;margin-right:40px}
